7	import type {
8	  AgentCard,
9	  Message,
10	  MessageSendParams,
11	  Task,
12	  TaskStatusUpdateEvent,
13	  TaskArtifactUpdateEvent,
14	} from '@a2a-js/sdk';
15	import type { AuthenticationHandler, Client } from '@a2a-js/sdk/client';
16	import {
17	  ClientFactory,
18	  ClientFactoryOptions,
19	  DefaultAgentCardResolver,
20	  JsonRpcTransportFactory,
21	  RestTransportFactory,
22	  createAuthenticatingFetchWithRetry,
23	} from '@a2a-js/sdk/client';
24	import { GrpcTransportFactory } from '@a2a-js/sdk/client/grpc';
25	import * as grpc from '@grpc/grpc-js';
26	import { v4 as uuidv4 } from 'uuid';
27	import { Agent as UndiciAgent, ProxyAgent } from 'undici';
28	import { normalizeAgentCard } from './a2aUtils.js';
29	import type { Config } from '../config/config.js';
30	import { debugLogger } from '../utils/debugLogger.js';
31	import { classifyAgentError } from './a2a-errors.js';
32	
33	/**
34	 * Result of sending a message, which can be a full message, a task,
35	 * or an incremental status/artifact update.
36	 */
37	export type SendMessageResult =
38	  | Message
39	  | Task
40	  | TaskStatusUpdateEvent
41	  | TaskArtifactUpdateEvent;
42	
43	// Remote agents can take 10+ minutes (e.g. Deep Research).
44	// Use a dedicated dispatcher so the global 5-min timeout isn't affected.
45	const A2A_TIMEOUT = 1800000; // 30 minutes
46	
47	/**
48	 * Orchestrates communication with remote A2A agents.
49	 * Manages protocol negotiation, authentication, and transport selection.
50	 */
51	export class A2AClientManager {
52	  // Each agent should manage their own context/taskIds/card/etc
53	  private clients = new Map<string, Client>();
54	  private agentCards = new Map<string, AgentCard>();
55	
56	  private a2aDispatcher: UndiciAgent | ProxyAgent;
57	  private a2aFetch: typeof fetch;
58	
59	  constructor(private readonly config: Config) {
60	    const proxyUrl = this.config.getProxy();
61	    const agentOptions = {
62	      headersTimeout: A2A_TIMEOUT,
63	      bodyTimeout: A2A_TIMEOUT,
64	    };
65	
66	    if (proxyUrl) {
67	      this.a2aDispatcher = new ProxyAgent({
68	        uri: proxyUrl,
69	        ...agentOptions,
70	      });
71	    } else {
72	      this.a2aDispatcher = new UndiciAgent(agentOptions);
73	    }
74	
75	    this.a2aFetch = (input, init) =>
76	      fetch(input, { ...init, dispatcher: this.a2aDispatcher } as RequestInit);
77	  }
78	
79	  /**
80	   * Loads an agent by fetching its AgentCard and caches the client.
81	   * @param name The name to assign to the agent.
82	   * @param agentCardUrl The full URL to the agent's card.
83	   * @param authHandler Optional authentication handler to use for this agent.
84	   * @returns The loaded AgentCard.
85	   */
86	  async loadAgent(
87	    name: string,
88	    agentCardUrl: string,
89	    authHandler?: AuthenticationHandler,
90	  ): Promise<AgentCard> {
91	    if (this.clients.has(name) && this.agentCards.has(name)) {
92	      throw new Error(`Agent with name '${name}' is already loaded.`);
93	    }
94	
95	    // Authenticated fetch for API calls (transports).
96	    let authFetch: typeof fetch = this.a2aFetch;
97	    if (authHandler) {
98	      authFetch = createAuthenticatingFetchWithRetry(
99	        this.a2aFetch,
100	        authHandler,
101	      );
102	    }
103	
104	    // Use unauthenticated fetch for the agent card unless explicitly required.
105	    // Some servers reject unexpected auth headers on the card endpoint (e.g. 400).
106	    const cardFetch = async (
107	      input: RequestInfo | URL,
108	      init?: RequestInit,
109	    ): Promise<Response> => {
110	      // Try without auth first
111	      const response = await this.a2aFetch(input, init);
112	
113	      // Retry with auth if we hit a 401/403
114	      if ((response.status === 401 || response.status === 403) && authFetch) {
115	        return authFetch(input, init);
116	      }
117	
118	      return response;
119	    };
120	
121	    const resolver = new DefaultAgentCardResolver({ fetchImpl: cardFetch });
122	    const rawCard = await resolver.resolve(agentCardUrl, '');
123	    // TODO: Remove normalizeAgentCard once @a2a-js/sdk handles
124	    // proto field name aliases (supportedInterfaces → additionalInterfaces,
125	    // protocolBinding → transport).
126	    const agentCard = normalizeAgentCard(rawCard);
127	
128	    const grpcUrl =
129	      agentCard.additionalInterfaces?.find((i) => i.transport === 'GRPC')
130	        ?.url ?? agentCard.url;
131	
132	    const clientOptions = ClientFactoryOptions.createFrom(
133	      ClientFactoryOptions.default,
134	      {
135	        transports: [
136	          new RestTransportFactory({ fetchImpl: authFetch }),
137	          new JsonRpcTransportFactory({ fetchImpl: authFetch }),
138	          new GrpcTransportFactory({
139	            grpcChannelCredentials: grpcUrl.startsWith('https://')
140	              ? grpc.credentials.createSsl()
141	              : grpc.credentials.createInsecure(),
142	          }),
143	        ],
144	        cardResolver: resolver,
145	      },
146	    );
147	
148	    try {
149	      const factory = new ClientFactory(clientOptions);
150	      const client = await factory.createFromAgentCard(agentCard);
151	
152	      this.clients.set(name, client);
153	      this.agentCards.set(name, agentCard);
154	
155	      debugLogger.debug(
156	        `[A2AClientManager] Loaded agent '${name}' from ${agentCardUrl}`,
157	      );
158	
159	      return agentCard;
160	    } catch (error: unknown) {
161	      throw classifyAgentError(name, agentCardUrl, error);
162	    }
163	  }
164	
165	  /**
166	   * Invalidates all cached clients and agent cards.
167	   */
168	  clearCache(): void {
169	    this.clients.clear();
170	    this.agentCards.clear();
171	    debugLogger.debug('[A2AClientManager] Cache cleared.');
172	  }
173	
174	  /**
175	   * Sends a message to a loaded agent and returns a stream of responses.
176	   * @param agentName The name of the agent to send the message to.
177	   * @param message The message content.
178	   * @param options Optional context and task IDs to maintain conversation state.
179	   * @returns An async iterable of responses from the agent (Message or Task).
180	   * @throws Error if the agent returns an error response.
181	   */
182	  async *sendMessageStream(
183	    agentName: string,
184	    message: string,
185	    options?: { contextId?: string; taskId?: string; signal?: AbortSignal },
186	  ): AsyncIterable<SendMessageResult> {
187	    const client = this.clients.get(agentName);
188	    if (!client) throw new Error(`Agent '${agentName}' not found.`);
189	
190	    const messageParams: MessageSendParams = {
191	      message: {
192	        kind: 'message',
193	        role: 'user',
194	        messageId: uuidv4(),
195	        parts: [{ kind: 'text', text: message }],
196	        contextId: options?.contextId,
197	        taskId: options?.taskId,
198	      },
199	    };
200	
201	    try {
202	      yield* client.sendMessageStream(messageParams, {
203	        signal: options?.signal,
204	      });
205	    } catch (error: unknown) {
206	      const prefix = `[A2AClientManager] sendMessageStream Error [${agentName}]`;
207	      if (error instanceof Error) {
208	        throw new Error(`${prefix}: ${error.message}`, { cause: error });
209	      }
210	      throw new Error(
211	        `${prefix}: Unexpected error during sendMessageStream: ${String(error)}`,
212	      );
213	    }
214	  }
215	
216	  /**
217	   * Retrieves a loaded agent card.
218	   * @param name The name of the agent.
219	   * @returns The agent card, or undefined if not found.
220	   */
221	  getAgentCard(name: string): AgentCard | undefined {
222	    return this.agentCards.get(name);
223	  }
224	
225	  /**
226	   * Retrieves a loaded client.
227	   * @param name The name of the agent.
228	   * @returns The client, or undefined if not found.
229	   */
230	  getClient(n
