 * from a URL, or by parsing an inline JSON string.
 */
export type AgentCardLoadOptions =
  | { type: 'url'; url: string }
  | { type: 'json'; json: string };

/**
 * Determines how a remote agent's card should be loaded based on its
 * definition. Prefers inline JSON over a URL when both are present.
 *
 * @param def The remote agent definition.
 * @returns The load options describing the source of the agent card.
 * @throws If neither `agentCardJson` nor `agentCardUrl` is present.
 */
export function getAgentCardLoadOptions(
  def: RemoteAgentDefinition,
): AgentCardLoadOptions {
  if (def.agentCardJson) {
    return { type: 'json', json: def.agentCardJson };
  }
  if (def.agentCardUrl) {
    return { type: 'url', url: def.agentCardUrl };
  }
  throw new Error(
    `Remote agent '${def.name}' has neither agentCardUrl nor agentCardJson`,
  );
}

