 * @param def The remote agent definition.
 * @returns The target URL, or `undefined` if it cannot be determined.
 */
export function getRemoteAgentTargetUrl(
  def: RemoteAgentDefinition,
): string | undefined {
  if (def.agentCardUrl) {
    return def.agentCardUrl;
  }
  if (def.agentCardJson) {
    try {
      const parsed = JSON.parse(def.agentCardJson) as { url?: unknown };
      if (typeof parsed.url === 'string') {
        return parsed.url;
      }
    } catch {
      return undefined;
    }
  }
  return undefined;
